  function openDemo(id) {
    const data = DEMO_DATA[id];
    if (!data) return;
    titleImg.src = data.title;
    // text
    let html = '';
    if (data.meta) html += '<div class="meta">' + data.meta.replace(/\n/g, '<br>') + '</div>';
    if (data.body) {
      const bodyHtml = data.body.split('\n').map(line => {
        const m = line.match(/^(\s*)(.*)/);
        return (m[1] ? m[1].replace(/ /g, '&nbsp;') : '') + m[2];
      }).join('<br>');
      html += '<div class="body">' + bodyHtml + '</div>';
    }
    descBox.innerHTML = html || '';
    descBox.scrollTop = 0;
    updateTextBorder(descBox);
    requestAnimationFrame(() => {
      descBox.scrollTop = 0;
      requestAnimationFrame(() => { descBox.scrollTop = 0; });
    });
    // thumbs
    thumbsS.innerHTML = '';
    data.screens.forEach((name, i) => {
      if (i >= SCREEN_SLOTS.length) return;
      const [px, py] = SCREEN_SLOTS[i];
      const d = document.createElement('div');
      d.className = 'thumb';
      d.style.cssText = 'left:'+px+'%;top:'+py+'%;width:48%;height:31%;';
      const img = document.createElement('img');
      img.src = 'assets/img/content/' + name + '.webp';
      img.draggable = false;
      d.appendChild(img);
      d.addEventListener('mouseenter', () => { largeImg.src = img.src; largePrev.classList.add('visible'); });
      d.addEventListener('mouseleave', () => largePrev.classList.remove('visible'));
      thumbsS.appendChild(d);
    });
    thumbsA.innerHTML = '';
    data.arts.forEach((name, i) => {
      if (i >= ART_SLOTS.length) return;
      const [px, py] = ART_SLOTS[i];
      const d = document.createElement('div');
      d.className = 'thumb';
      d.style.cssText = 'left:'+px+'%;top:'+py+'%;width:48%;height:48%;';
      const img = document.createElement('img');
      img.src = 'assets/img/content/' + name + '.webp';
      img.draggable = false;
      d.appendChild(img);
      d.addEventListener('mouseenter', () => { largeImg.src = img.src; largePrev.classList.add('visible'); });
      d.addEventListener('mouseleave', () => largePrev.classList.remove('visible'));
      thumbsA.appendChild(d);
    });
    showScene('demo');
  }


