  const patchTip = document.getElementById('patch-tip');
  document.querySelectorAll('.hs-patch').forEach(hs => {
    hs.addEventListener('mouseenter', function() {
      hideLabels();
      const idx = +this.dataset.idx;
      const txt = PATCH_TEXTS[idx].text;
      patchTip.textContent = txt;
      patchTip.style.left = '0';
      patchTip.style.top = '0';
      patchTip.style.visibility = 'hidden';
      patchTip.classList.add('visible');
      // measure after content
      const tipH = patchTip.offsetHeight;
      const tipW = patchTip.offsetWidth;
      const rect = this.getBoundingClientRect();
      const sceneRect = this.closest('.scene').getBoundingClientRect();
      const relTop = (rect.top - sceneRect.top) / sceneRect.height;
      let left = ((rect.left - sceneRect.left) / sceneRect.width * 100) + 3;
      left = Math.max(2, Math.min(left, 100 - (tipW / sceneRect.width * 100) - 2));
      let topPct;
      if (relTop < 0.52) {
        topPct = ((rect.bottom - sceneRect.top) / sceneRect.height * 100) + 0.8;
      } else {
        topPct = ((rect.top - sceneRect.top - tipH) / sceneRect.height * 100) - 0.8;
      }
      left = Math.max(1, Math.min(left, 60));
      if (topPct < 2) topPct = 2;
      if (topPct > 78) topPct = 78;
      // if tip would go past right edge, shift left
      const tipWpct = (patchTip.offsetWidth / sceneRect.width) * 100;
      if (left + tipWpct > 98) left = Math.max(1, 98 - tipWpct);
      const tipHpct = (patchTip.offsetHeight / sceneRect.height) * 100;
      if (topPct + tipHpct > 96) topPct = Math.max(2, 96 - tipHpct);
      patchTip.style.left = left + '%';
      patchTip.style.top = topPct + '%';
      patchTip.style.visibility = 'visible';
    });
    hs.addEventListener('mouseleave', () => {
      patchTip.classList.remove('visible');
    });
    hs.addEventListener('click', e => { e.stopPropagation(); showToast(); });
  });


